export function formulaMass(formula){
 const tokens=[...formula.matchAll(/([A-Z][a-z]?)(\d*)/g)];
 if(tokens.map(x=>x[0]).join('')!==formula||!tokens.length)throw Error('Unsupported library formula');
 return Number(tokens.reduce((sum,[,el,count])=>{if(!atomicWeights[el])throw Error('Unknown library element');return sum+atomicWeights[el]*Number(count||1);},0).toFixed(3));
}
function equationExample(id,label,category,equation,reactants,products,greenNote,source,context=''){
 const make=([name,formula,coeff=1])=>({...row(name,'',formulaMass(formula),coeff),formula});
 return {id,label,category,equation,subtitle:greenNote,source:references[source],kind:'Equation template',reaction:{...emptyReaction(),name:label,reactants:reactants.map(make),products:products.map(make),balanced:true,libraryId:id,equation,category,source:references[source],referenceContext:context,notes:`Textbook equation template. Quantities, yield and operating conditions are intentionally unspecified; not a laboratory procedure. Formula masses are rounded, formula-derived values. ${greenNote} ${context}`}};
}
